package com.amit.jobagent.application;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="application_tracker")class ApplicationTracker{@Id UUID id;@Column(name="user_id",nullable=false,updatable=false,length=150)String userId;@Column(name="job_posting_id",nullable=false,updatable=false)UUID jobId;@Column(name="application_handoff_id",nullable=false,updatable=false,unique=true)UUID handoffId;@Column(name="application_package_revision_id",nullable=false,updatable=false)UUID revisionId;@Column(name="job_evaluation_id",nullable=false,updatable=false)UUID evaluationId;@Enumerated(EnumType.STRING)@Column(name="current_status",nullable=false,length=30)ApplicationTrackingStatus status;@Column(name="submitted_reported_at",nullable=false,updatable=false)Instant submittedAt;@Column(name="last_activity_at",nullable=false)Instant lastActivityAt;@Column(name="archived_at")Instant archivedAt;@Version@Column(name="record_version",nullable=false)long version;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;protected ApplicationTracker(){}ApplicationTracker(ApplicationHandoff h,ApplicationPackageRevision r,String user){id=UUID.randomUUID();userId=user;jobId=h.jobId;handoffId=h.id;revisionId=r.id;evaluationId=r.evaluationId;status=ApplicationTrackingStatus.SUBMITTED;submittedAt=Instant.now();lastActivityAt=submittedAt;createdAt=submittedAt;updatedAt=submittedAt;}void status(ApplicationTrackingStatus s){status=s;lastActivityAt=Instant.now();updatedAt=lastActivityAt;}void archive(){archivedAt=Instant.now();updatedAt=archivedAt;}void restore(){archivedAt=null;updatedAt=Instant.now();}}
